Here's the code for a simple server-side implementation (stun_server.js):

```javascript
const stun = require('stun-server');

const server = stun.createServer();

server.on('request', handleRequest);

function handleRequest(req, res) {
  const attributes = {
    'message-id': req.getMessageId(),
    'software': 'stun_server',
  };

  if (req.methods.includes('BIND')) {
    // Respond to binding requests with a Success response.
    stun.attributes(response, attributes);
    return res.statusCode = 200;
  }

  // For other types of requests, respond with an error.
  res.statusCode = 400;

}
```

